-- Eurostat REST tables (JSON-stat, geo=BE)
-- Generated by scripts/onboard.ts from src/data/eurostat.ts. One statement per call (Zetaris Lightning SQL).
-- The COMPILE USL statement is multi-table and must be sent as ONE statement.

-- lightning database
CREATE LIGHTNING DATABASE EUROSTAT_REST DESCRIBE BY "Eurostat REST API JSON-stat source, Causeway";

-- rest table hicp_choc_i15
CREATE LIGHTNING REST TABLE hicp_choc_i15 FROM EUROSTAT_REST REQUEST(endpoint "https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/prc_hicp_midx?format=JSON&lang=EN&geo=BE&coicop=CP01183&unit=I15&freq=M&sinceTimePeriod=2019-01", method "get", response_type "json", http_encoding "URLENCODED") HEADER () BODY ();

